import {readFile, writeFile} from "node:fs/promises";

/*
 * 변경 기록의 공개 문서 동기화. npm에 포함하는 CHANGELOG.md를 원본으로 사용
 *
 *   - 버전별 본문은 영어 하나를 유지, 언어별 문서 탐색 정보와 업데이트 안내만 추가
 */

/**
 * 영어 변경 기록 문서의 frontmatter와 업데이트 안내
 */
const changelog_header = [
    "---",
    "name: Changelog",
    "label: Changes and upgrade notes by version",
    "group: Updates",
    "order: 10",
    "---",
    "",
    "<!-- Generated by pnpm sync:docs from the repository CHANGELOG.md. -->",
    "",
    "Changes by version. `Unreleased` lists changes that are not published to npm yet.",
    "Check the installed version with `pnpm exec for-humanity --version`.",
    "Before updating, read the **Breaking change** and **Upgrade** notes of the target version. In `0.x`, a minor update may also require changes to documents or configuration.",
    "",
    "```sh",
    "pnpm add -D --save-exact for-humanity@latest",
    "```",
    "",
    "Package files for each version are available from [GitHub Releases](https://github.com/minu-ha/for-humanity/releases).",
].join("\n");

/**
 * 한국어 변경 기록 문서의 frontmatter와 업데이트 안내
 */
const changelog_header_ko = [
    "---",
    "name: Changelog",
    "label: 버전별 변경 사항과 업데이트 방법",
    "group: Updates",
    "order: 10",
    "---",
    "",
    "<!-- Generated by pnpm sync:docs from the repository CHANGELOG.md. -->",
    "",
    "버전별 변경 사항입니다. `Unreleased`는 아직 npm에 공개하지 않은 변경입니다.",
    "설치한 버전은 `pnpm exec for-humanity --version`으로 확인합니다.",
    "업데이트하기 전에 해당 버전의 **Breaking change**와 **Upgrade** 안내를 확인합니다. `0.x`에서는 minor 업데이트에도 문서나 설정을 수정해야 할 수 있습니다.",
    "",
    "```sh",
    "pnpm add -D --save-exact for-humanity@latest",
    "```",
    "",
    "버전별 패키지 파일은 [GitHub Releases](https://github.com/minu-ha/for-humanity/releases)에서 받을 수 있습니다.",
].join("\n");

const source = await readFile(new URL("../CHANGELOG.md", import.meta.url), "utf8");
const body = source.replace(/^# Changelog\s*\n/, "").trim();

await writeFile(new URL("../content/public/changelog.md", import.meta.url), `${changelog_header}\n\n${body}\n`);
await writeFile(new URL("../content/ko/public/changelog.md", import.meta.url), `${changelog_header_ko}\n\n${body}\n`);
